(5, 2, 'HK 17g Full Metal Gear Micro Servo (TGY2804MG) за 1/16 1/18 1/24 мащаб RC кола Traxxas Slash Plane DIY Project Arduino Robotics', 'hk-17g-full-metal-gear-micro-servo-tgy2804mg-for-116-118-124-scale-rc-car-traxxas-slash-plane-diy-project-arduino-robotics', 'Компактно микро серво с метално зъбно колело от 17 g. Лека опция за мини RC автомобили, повърхности за малки самолети и проекти за роботика „Направи си сам“.', 7.99, NULL, NULL, 37, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/k/hk_21g_full_metal_gear_micro_servo_tgy2804mg_for_116_scale_118_scale_124_scale_rc_car_traxxas_slash_plane_diy_project_arduino_robotics_1_.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/k/hk_21g_full_metal_gear_micro_servo_tgy2804mg_for_116_scale_118_scale_124_scale_rc_car_traxxas_slash_plane_diy_project_arduino_robotics_5_.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/k/hk_21g_full_metal_gear_micro_servo_tgy2804mg_for_116_scale_118_scale_124_scale_rc_car_traxxas_slash_plane_diy_project_arduino_robotics_4_.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/k/hk_21g_full_metal_gear_micro_servo_tgy2804mg_for_116_scale_118_scale_124_scale_rc_car_traxxas_slash_plane_diy_project_arduino_robotics_3_.jpg', NULL, 1, '2026-02-07 19:54:07'),
(6, 2, 'HK 9g Full Metal Gear Micro Servo (TGY2301MG) за 1/16 1/18 1/24 мащаб RC кола Buggy Traxxas Slash Rustler Plane FPV DIY Project Arduino Robotics', 'hk-9g-full-metal-gear-micro-servo-tgy2301mg-for-116-118-124-scale-rc-car-buggy-traxxas-slash-rustler-plane-fpv-diy-project-arduino-robotics', 'Изключително леко 9 g микро серво с метално зъбно колело. Перфектен за RC превозни средства в мащаб 1/16-1/24 и самолети на закрито, изискващи минимално тегло.', 6.99, NULL, NULL, 7, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/k/hk_13.5g_full_metal_gear_micro_servo_tgy2301mg_for_116_scale_118_scale_124_scale_rc_car_buggy_traxxas_slash_rustler_plane_fpv_diy_project_arduino_robotics_1_.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/k/hk_13.5g_full_metal_gear_micro_servo_tgy2301mg_for_116_scale_118_scale_124_scale_rc_car_buggy_traxxas_slash_rustler_plane_fpv_diy_project_arduino_robotics_5_.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/k/hk_13.5g_full_metal_gear_micro_servo_tgy2301mg_for_116_scale_118_scale_124_scale_rc_car_buggy_traxxas_slash_rustler_plane_fpv_diy_project_arduino_robotics_4_.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/k/hk_13.5g_full_metal_gear_micro_servo_tgy2301mg_for_116_scale_118_scale_124_scale_rc_car_buggy_traxxas_slash_rustler_plane_fpv_diy_project_arduino_robotics_3_.jpg', NULL, 1, '2026-02-07 19:54:07'),
(7, 2, 'HK 15KG Full Metal Gear Standard Servo (TGY4016MG) за 1/8 1/10 мащаб RC Crawler Truck Axial SCX10 Plane Robot Arm Arduino Robotics', 'hk-15kg-full-metal-gear-standard-servo-tgy4016mg-for-18-110-scale-rc-crawler-truck-axial-scx10-plane-robot-arm-arduino-robotics', '15 кг изцяло метално стандартно серво. Гъвкаво серво устройство със среден въртящ момент, подходящо за верижни машини 1/8-1/10 и самолети със среден размах на крилата.', 8.99, NULL, NULL, 6, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/k/hk_16.3kg_full_metal_gear_standard_servo_tgy4016mg_for_18_scale_110_scale_rc_crawler_truck_axial_scx10_plane_robot_arm_arduino_robotics_1_.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/k/hk_16.3kg_full_metal_gear_standard_servo_tgy4016mg_for_18_scale_110_scale_rc_crawler_truck_axial_scx10_plane_robot_arm_arduino_robotics_5_.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/k/hk_16.3kg_full_metal_gear_standard_servo_tgy4016mg_for_18_scale_110_scale_rc_crawler_truck_axial_scx10_plane_robot_arm_arduino_robotics_4_.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/k/hk_16.3kg_full_metal_gear_standard_servo_tgy4016mg_for_18_scale_110_scale_rc_crawler_truck_axial_scx10_plane_robot_arm_arduino_robotics_3_.jpg', NULL, 1, '2026-02-07 19:54:07'),
