(10, 2, 'JST-XH към JST LED захранващ кабел (4 JST)', 'to-ower-istribution-ead-4', 'JST-XH към JST разпределителен кабел с 4 JST изхода. Идеален за захранване на LED ленти от балансиращ конектор.', 1.58, NULL, NULL, 22, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/23133_1__2.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/23133_1__3.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/23133_1_.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/23133_1__1.jpg', '', 1, '2026-02-07 19:54:07'),
(11, 2, 'Т-конектор към адаптер за батерия EC5 (2 бр./чанта)', 't-connector-to-ec5-battery-adapter-2pcsbag', 'Адаптер преобразува T-конектор (Tamiya) в EC5. Опаковка от 2. Позволява използването на по-стари батерии с T-конектор със съвместимо с EC5 оборудване.', 3.99, NULL, NULL, 10, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/62921.jpg', NULL, NULL, NULL, NULL, 1, '2026-02-07 19:54:07'),
(13, 2, 'Комплект за монтаж на скоби за кабелни връзки (12 части)', 'cable-tie-clip-mounting-set-12-piece', 'Комплект за монтаж на скоби за кабелни връзки с 12 разнообразни скоби за организиране на кабелни снопове вътре в RC модели.', 2.49, NULL, NULL, 6, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/81074.jpg', NULL, NULL, NULL, NULL, 1, '2026-02-07 19:54:07'),
