(161, 2, 'Futaba 60mm 26AWG Servo Y Lead (5 бр.)', 'futaba-60mm-26awg-servo-y-lead-5pcs', 'Futaba 60 мм серво Y повод. 26 AWG проводник. Удвоява един приемен канал, за да задвижва две сервосистеми. Опаковка от 5 бр.', 2.99, NULL, NULL, 19, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/2/1/215291.jpg', NULL, NULL, NULL, NULL, 1, '2026-02-07 19:54:07'),
(162, 2, 'Двустранна лента (прозрачна) 25 mm x 1 m', 'double-sided-tape-clear-25mm-x-1m', 'Прозрачна двустранна самозалепваща лента. 25 мм ширина, 1 м на ролка. Силна връзка за закрепване на ESC, приемник и окабеляване.', 1.99, NULL, NULL, 10, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/42984_1__1.jpg', NULL, NULL, NULL, NULL, 1, '2026-02-07 19:54:07'),
(163, 6, 'Превключвател, управляван от приемник Turnigy', 'turnigy-receiver-controlled-switch', 'Електронен ключ, активиран от приемника. Позволява серво канал за управление на верига за включване/изключване до 10 A.', 4.99, NULL, NULL, 19, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/46040_1__2.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/46040_1__4.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/46040_1_.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/46040s.jpg', NULL, 1, '2026-02-07 19:54:07'),
(164, 6, 'Turnigy EVA мек калъф за носене на предаватели X14/X14S (черен)', 'turnigy-eva-soft-carry-case-for-x14x14s-transmitters-black', 'Чанта за носене от EVA пяна за предаватели Turnigy X14/X14S. Черен с подплатена вътрешност и презрамка.', 19.99, NULL, NULL, 14, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/9/2/9236720210-1-r_1.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/9/2/9236720210-2-r_3.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/9/2/9236720210-6-r_1.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/9/2/9236720210-3-r_3.jpg', NULL, 1, '2026-02-07 19:54:07'),
(165, 6, 'Каишка за врата на предавателя Turnigy', 'turnigy-transmitter-neck-strap', 'Регулируема неопренова лента за врат за RC предаватели. Универсална скоба, съвместима с повечето марки предаватели.', 5.99, NULL, NULL, 29, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/9/2/9236720211-r.jpg', NULL, NULL, NULL, NULL, 1, '2026-02-07 19:54:07'),
(166, 6, 'Персонализирана лицева плоча на предавател Turnigy 9XR - червен металик', 'turnigy-9xr-transmitter-custom-faceplate-metallic-red', 'Персонализирана метална червена лицева плоча за предавател Turnigy 9XR. Монтиране с щракване, не са необходими инструменти.', 7.99, NULL, NULL, 27, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/39632.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/legacy/catalog/39632s1_mark.jpg', NULL, NULL, NULL, 1, '2026-02-07 19:54:07'),
(167, 6, 'FrSky Taranis X-Lite предавател BRACE Lite Plus Red дълги и къси краища на карданния стик', 'frsky-taranis-x-lite-transmitter-brace-lite-plus-red-long-and-short-gimbal-stick-ends', 'Дълги и къси алуминиеви краища на кардана за FrSky Taranis X-Lite и X-Lite Plus предаватели. Червен цвят.', 6.99, NULL, NULL, 9, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/2/0/203703.jpg', NULL, NULL, NULL, NULL, 1, '2026-02-07 19:54:07'),
(168, 2, 'HX 5010 Цифрово серво с двоен лагер 25T 6,5 кг / 0,16 сек / 39,2 г', 'hx-5010-twin-bearing-digital-servo-25t-65kg-016sec-392g', 'HX 5010 цифрово серво с двоен лагер с 25T изходен шлиц. 6,5 kg въртящ момент и 0,16 s скорост при 6 V.', 9.99, NULL, NULL, 15, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/x/hx5010-1-re.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/h/x/hx5010-2-re.jpg', NULL, NULL, NULL, 1, '2026-02-07 19:54:07'),
(169, 2, 'Turnigy TGY-WP23 Водоустойчива цифрова сервосистема Metal Gear 23 кг / 0,12 сек / 75 г', 'turnigy-tgy-wp23-waterproof-metal-gear-digital-servo-23kg-012sec-75g', 'Водоустойчиво цифрово серво с метална предавка IP67. 23 kg въртящ момент при 7,4 V. Подходящ за тежкотоварни превозни средства.', 22.99, NULL, NULL, 10, 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/1/2/122194.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/1/2/122194_1.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/1/2/122194_2.jpg', 'https://cdn-global-hk.hobbyking.com/media/catalog/product/cache/1/thumbnail/180x100/9df78eab33525d08d6e5fb8d27136e95/1/2/122194_3.jpg', NULL, 1, '2026-02-07 19:54:07'),
